    ExecutionSteps  []ExecutionStep `json:"executionSteps"`
    EstimatedSeries int64           `json:"estimatedSeries"`
    EstimatedSamples int64          `json:"estimatedSamples"`
    Warnings       []string        `json:"warnings"`
